{
  "explanation": "A radian is a way of measuring angles using the circle itself: it is the central angle formed when the arc length along the circle is exactly equal to the radius. Since angle = arc length / radius (θ = s/r), one radian is about 57.3°, and a full circle (s = 2πr) is 2π ≈ 6.28 radians. In the animation, watch the radius sweep out until the yellow arc has the same length as r — that angle is exactly 1 radian. Then drag the orange point around the circle or use the slider to see how arc length, radians, and degrees stay linked.",
  "manimCode": "// ---- What is a radian? ----
const C = [-2.5, 0, 0];
const R = 2;
let ang = 0;

// Static pieces
const title = new Text({ text: 'What is a radian?', color: WHITE, fontSize: 42 });
title.moveTo([0, 3.4, 0]);

const circle = new Circle({ radius: R, color: BLUE });
circle.moveTo(C);
const centerDot = new Dot({ point: [C[0], C[1], 0], color: WHITE });

const fixedRadius = new Line({ start: [C[0], C[1], 0], end: [C[0] + R, C[1], 0], color: WHITE });
const rLabel = new Text({ text: 'r', color: WHITE, fontSize: 30 });
rLabel.moveTo([C[0] + R / 2, C[1] - 0.35, 0]);

// Moving radius (2-vertex polygon so endpoints can update)
const movingRadius = new Polygon({ vertices: [[C[0], C[1], 0], [C[0] + R, C[1], 0]], color: ORANGE });
movingRadius.setStrokeWidth(4).setFillOpacity(0);
movingRadius.addUpdater(() => {
  movingRadius.setVertices([
    [C[0], C[1], 0],
    [C[0] + R * Math.cos(ang), C[1] + R * Math.sin(ang), 0]
  ]);
});

// Filled sector showing the angle
const sector = new Polygon({ vertices: [[C[0], C[1], 0], [C[0] + R, C[1], 0], [C[0] + R, C[1] + 0.001, 0]], color: YELLOW });
sector.setFill(YELLOW, 0.25);
sector.setStrokeWidth(2);
sector.addUpdater(() => {
  const a = Math.max(ang, 0.0001);
  const pts = [[C[0], C[1], 0]];
  const n = Math.max(2, Math.ceil(72 * a / (2 * Math.PI)));
  for (let i = 0; i <= n; i++) {
    const t0 = a * i / n;
    pts.push([C[0] + R * Math.cos(t0), C[1] + R * Math.sin(t0), 0]);
  }
  sector.setVertices(pts);
});

// Draggable tip of the moving radius
const tip = new Dot({ point: [C[0] + R, C[1], 0], color: ORANGE });

// Highlighted arc (rebuilt whenever the angle changes)
let arcGroup = null;
function makeArcGroup(a) {
  const segs = [];
  const n = Math.max(2, Math.ceil(96 * a / (2 * Math.PI)));
  for (let i = 0; i < n; i++) {
    const a0 = a * i / n;
    const a1 = a * (i + 1) / n;
    const seg = new Line({
      start: [C[0] + R * Math.cos(a0), C[1] + R * Math.sin(a0), 0],
      end: [C[0] + R * Math.cos(a1), C[1] + R * Math.sin(a1), 0],
      color: YELLOW
    });
    seg.setStrokeWidth(6);
    segs.push(seg);
  }
  return new VGroup(...segs);
}
function rebuildArc(a) {
  if (arcGroup) scene.remove(arcGroup);
  arcGroup = null;
  if (a > 0.005) {
    arcGroup = makeArcGroup(a);
    scene.add(arcGroup);
  }
}

// Little "s" label riding the arc midpoint
let sLabel = null;
function updateSLabel(a) {
  if (sLabel) { scene.remove(sLabel); sLabel = null; }
  if (a > 0.15) {
    sLabel = new Text({ text: 's', color: YELLOW, fontSize: 30 });
    const mid = a / 2;
    sLabel.moveTo([C[0] + (R + 0.55) * Math.cos(mid), C[1] + (R + 0.55) * Math.sin(mid), 0]);
    scene.add(sLabel);
  }
}

// Numeric readout (Text is immutable -> remove + recreate)
let valLabel = null;
function updateValLabel(a) {
  const deg = a * 180 / Math.PI;
  const str = 's = ' + a.toFixed(2) + ' r     θ = ' + a.toFixed(2) + ' rad  =  ' + deg.toFixed(1) + '°';
  if (valLabel) scene.remove(valLabel);
  valLabel = new Text({ text: str, color: WHITE, fontSize: 24 });
  valLabel.moveTo([3.2, 1.0, 0]);
  scene.add(valLabel);
}

function setAngle(a) {
  ang = Math.min(Math.max(a, 0), 2 * Math.PI);
  tip.moveTo([C[0] + R * Math.cos(ang), C[1] + R * Math.sin(ang), 0]);
  rebuildArc(ang);
  updateSLabel(ang);
  updateValLabel(ang);
}

// ---- Intro animation ----
await scene.play(new Write(title));
await scene.play(new Create(circle));
await scene.play(new FadeIn(centerDot));
await scene.play(new Create(fixedRadius));
await scene.play(new Write(rLabel));
scene.add(sector, movingRadius, tip);

// Sweep the radius until the arc length equals r (1 radian)
for (let i = 1; i <= 40; i++) {
  ang = i / 40;
  tip.moveTo([C[0] + R * Math.cos(ang), C[1] + R * Math.sin(ang), 0]);
  await scene.wait(0.03);
}

arcGroup = makeArcGroup(1);
await scene.play(new FadeIn(arcGroup));
updateSLabel(1);

const formula = new MathTex({ latex: '\\theta = \\frac{s}{r}' });
await formula.waitForRender();
formula.moveTo([3.2, 2.4, 0]);
await scene.play(new Write(formula));

const approx = new Text({ text: '1 radian ≈ 57.30°', color: GOLD, fontSize: 28 });
approx.moveTo([3.2, 1.7, 0]);
await scene.play(new Write(approx));

updateValLabel(1);

const note1 = new Text({ text: 'When the arc length s equals the radius r, the angle is exactly 1 radian.', color: GRAY, fontSize: 20 });
note1.moveTo([0, -3.05, 0]);
const note2 = new Text({ text: 'A full circle has s = 2πr, so a full turn is 2π ≈ 6.28 radians.', color: GRAY, fontSize: 20 });
note2.moveTo([0, -3.5, 0]);
await scene.play(new FadeIn(note1));
await scene.play(new FadeIn(note2));

// ---- Interactivity ----
makeDraggable(tip, scene, {
  onDrag: (mob, pos) => {
    let a = Math.atan2(pos[1] - C[1], pos[0] - C[0]);
    if (a < 0) a += 2 * Math.PI;
    setAngle(a);
  }
});

const controls = new Controls(scene, { position: 'bottom-right' });
controls.addSlider({ label: 'Arc length s (units of r)', min: 0, max: 2 * Math.PI, value: 1, step: 0.01, onChange: (v) => setAngle(v) });
controls.addButton({ label: 's = r  (1 rad)', onClick: () => setAngle(1) });
controls.addButton({ label: 's = πr  (π rad)', onClick: () => setAngle(Math.PI) });
controls.addButton({ label: 's = 2πr (full turn)', onClick: () => setAngle(2 * Math.PI) });

await scene.wait(999999);"
}

